campo.campo:
( select to_jsonb(array_agg(x)) from (
		select q160_descricao as descricao, q165_aliquotaimposto as valor
		from issgsanexosfaixasimpostosvalores inner join issgscadimpostos on q160_sequencial = q165_issgscadimpostos where q165_issgsanexosfaixasimpostoslimites = q164_sequencial ) as x)
